// Command csvstat profiles the columns of a CSV file.
package main
import (
	"os"
	"csvstat/internal/cli"
)
func main() {
	os.Exit(cli.Run(os.Args[1:], os.Stdout, os.Stderr))
}
package cli
import (
	"errors"
	"flag"
	"fmt"
	"io"
	"strconv"
)
// Options is the parsed command line. ColumnSet, FreqSet and TopSet record
// whether the option was given, so an empty value is distinguishable from an
// absent option.
type Options struct {
	Column    string
	ColumnSet bool
	Freq      string
	FreqSet   bool
	Top       int
	TopSet    bool
	File      string
}
var errRepeated = errors.New("option given more than once")
// stringOption is a flag value that records presence and refuses repetition.
type stringOption struct {
	value *string
	set   *bool
}
func (o *stringOption) String() string {
	if o == nil || o.value == nil {
		return ""
	}
	return *o.value
}
func (o *stringOption) Set(v string) error {
	if *o.set {
		return errRepeated
	}
	*o.value = v
	*o.set = true
	return nil
}
// intOption is a flag value holding a decimal integer that refuses repetition.
type intOption struct {
	value *int
	set   *bool
}
func (o *intOption) String() string {
	if o == nil || o.value == nil {
		return ""
	}
	return strconv.Itoa(*o.value)
}
func (o *intOption) Set(v string) error {
	if *o.set {
		return errRepeated
	}
	n, err := strconv.Atoi(v)
	if err != nil {
		return fmt.Errorf("%q is not a decimal integer", v)
	}
	*o.value = n
	*o.set = true
	return nil
}
// ParseArgs parses options followed by exactly one file argument. Parsing stops
// at the first non-option argument, which must be the file, so any later
// argument, including an option, is an error.
func ParseArgs(args []string) (Options, error) {
	var opts Options
	fs := flag.NewFlagSet("csvstat", flag.ContinueOnError)
	fs.SetOutput(io.Discard)
	fs.Var(&stringOption{&opts.Column, &opts.ColumnSet}, "column", "")
	fs.Var(&stringOption{&opts.Freq, &opts.FreqSet}, "freq", "")
	fs.Var(&intOption{&opts.Top, &opts.TopSet}, "top", "")
	if err := fs.Parse(args); err != nil {
		return Options{}, err
	}
	rest := fs.Args()
	switch len(rest) {
	case 0:
		return Options{}, errors.New("missing file argument")
	case 1:
		opts.File = rest[0]
		return opts, nil
	default:
		return Options{}, fmt.Errorf("unexpected argument %q after file or extra file", rest[1])
	}
}
package cli
import "testing"
func TestParseArgsFileOnly(t *testing.T) {
	opts, err := ParseArgs([]string{"data.csv"})
	if err != nil {
		t.Fatalf("ParseArgs: unexpected error: %v", err)
	}
	if want := (Options{File: "data.csv"}); opts != want {
		t.Fatalf("Options = %+v, want %+v", opts, want)
	}
}
func TestParseArgsColumn(t *testing.T) {
	opts, err := ParseArgs([]string{"--column", "name", "data.csv"})
	if err != nil {
		t.Fatalf("ParseArgs: unexpected error: %v", err)
	}
	if want := (Options{Column: "name", ColumnSet: true, File: "data.csv"}); opts != want {
		t.Fatalf("Options = %+v, want %+v", opts, want)
	}
}
func TestParseArgsFreqTop(t *testing.T) {
	opts, err := ParseArgs([]string{"--freq", "name", "--top", "3", "data.csv"})
	if err != nil {
		t.Fatalf("ParseArgs: unexpected error: %v", err)
	}
	want := Options{Freq: "name", FreqSet: true, Top: 3, TopSet: true, File: "data.csv"}
	if opts != want {
		t.Fatalf("Options = %+v, want %+v", opts, want)
	}
}
func TestParseArgsEmptyValueIsSet(t *testing.T) {
	opts, err := ParseArgs([]string{"--column", "", "data.csv"})
	if err != nil {
		t.Fatalf("ParseArgs: unexpected error: %v", err)
	}
	if !opts.ColumnSet || opts.Column != "" {
		t.Fatalf("Options = %+v, want ColumnSet with empty Column", opts)
	}
}
func TestParseArgsMissingFile(t *testing.T) {
	if _, err := ParseArgs([]string{"--column", "name"}); err == nil {
		t.Fatal("ParseArgs with no file: got nil error, want error")
	}
}
func TestParseArgsExtraFile(t *testing.T) {
	if _, err := ParseArgs([]string{"a.csv", "b.csv"}); err == nil {
		t.Fatal("ParseArgs with two files: got nil error, want error")
	}
}
func TestParseArgsUnknownOption(t *testing.T) {
	if _, err := ParseArgs([]string{"--frobnicate", "data.csv"}); err == nil {
		t.Fatal("ParseArgs with unknown option: got nil error, want error")
	}
}
func TestParseArgsMissingValue(t *testing.T) {
	for _, args := range [][]string{{"--top"}, {"--freq"}, {"--top", "data.csv"}} {
		if _, err := ParseArgs(args); err == nil {
			t.Errorf("ParseArgs(%q): got nil error, want error", args)
		}
	}
}
func TestParseArgsOptionsAfterFile(t *testing.T) {
	if _, err := ParseArgs([]string{"data.csv", "--column", "name"}); err == nil {
		t.Fatal("ParseArgs with option after file: got nil error, want error")
	}
}
func TestParseArgsRepeatedOption(t *testing.T) {
	if _, err := ParseArgs([]string{"--column", "a", "--column", "b", "data.csv"}); err == nil {
		t.Fatal("ParseArgs with repeated --column: got nil error, want error")
	}
}
func TestParseArgsTopMustBeDecimal(t *testing.T) {
	if _, err := ParseArgs([]string{"--top", "0x10", "data.csv"}); err == nil {
		t.Fatal("ParseArgs with --top 0x10: got nil error, want error")
	}
}
package cli
import (
	"bytes"
	"encoding/csv"
	"errors"
	"fmt"
	"io"
	"os"
	"csvstat/internal/csvdata"
)
// Exit codes. Only cmd/csvstat calls os.Exit with the value Run returns.
const (
	exitOK          = 0
	exitOperational = 1
	exitUsage       = 2
	exitRejected    = 3
)
// Run executes csvstat with args, which excludes the program name, and returns
// the process exit code. Stdout is written only on success; diagnostics go to
// stderr. Only cmd/csvstat calls os.Exit with this value.
func Run(args []string, stdout io.Writer, stderr io.Writer) int {
	opts, err := ParseArgs(args)
	if err != nil {
		fmt.Fprintf(stderr, "csvstat: %v\n", err)
		return exitUsage
	}
	f, err := os.Open(opts.File)
	if err != nil {
		fmt.Fprintf(stderr, "csvstat: %v\n", err)
		return exitOperational
	}
	defer f.Close()
	table, err := csvdata.Read(f)
	if err != nil {
		fmt.Fprintf(stderr, "csvstat: %s: %v\n", opts.File, err)
		return readFailureExit(err)
	}
	csvdata.Trim(table)
	if err := csvdata.Validate(table); err != nil {
		fmt.Fprintf(stderr, "csvstat: %s: %v\n", opts.File, err)
		return exitRejected
	}
	var rows [][]string
	switch {
	case opts.FreqSet:
		rows, err = freqRows(table, opts)
		if err != nil {
			fmt.Fprintf(stderr, "csvstat: %v\n", err)
			return exitUsage
		}
	case opts.ColumnSet:
		// Column output is not part of this build; the run succeeds with no output as before.
		return exitOK
	default:
		rows = profileRows(table)
	}
	return writeRows(stdout, stderr, rows)
}
// writeRows encodes rows as RFC 4180 CSV with \n line endings. The whole output is built in memory
// first, so stdout receives nothing unless encoding succeeds.
func writeRows(stdout io.Writer, stderr io.Writer, rows [][]string) int {
	var buf bytes.Buffer
	if err := csv.NewWriter(&buf).WriteAll(rows); err != nil {
		fmt.Fprintf(stderr, "csvstat: %v\n", err)
		return exitOperational
	}
	if _, err := stdout.Write(buf.Bytes()); err != nil {
		fmt.Fprintf(stderr, "csvstat: %v\n", err)
		return exitOperational
	}
	return exitOK
}
// readFailureExit maps a Read error to an exit code: a CSV syntax error is
// rejected input, while any other failure to read the file is operational.
func readFailureExit(err error) int {
	var parseErr *csv.ParseError
	if errors.As(err, &parseErr) {
		return exitRejected
	}
	return exitOperational
}
package cli
import (
	"bytes"
	"os"
	"path/filepath"
	"testing"
)
// runWith writes content to a temporary file and runs the command on it.
func runWith(t *testing.T, content string) (code int, stdout *bytes.Buffer, stderr *bytes.Buffer) {
	t.Helper()
	path := filepath.Join(t.TempDir(), "input.csv")
	if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
		t.Fatalf("write input: %v", err)
	}
	return runArgs(t, path)
}
func runArgs(t *testing.T, args ...string) (code int, stdout *bytes.Buffer, stderr *bytes.Buffer) {
	t.Helper()
	stdout, stderr = &bytes.Buffer{}, &bytes.Buffer{}
	code = Run(args, stdout, stderr)
	return code, stdout, stderr
}
func TestRunValidFileExitsZero(t *testing.T) {
	code, _, _ := runWith(t, "a,b\n1,2\n")
	if code != exitOK {
		t.Fatalf("exit code = %d, want %d", code, exitOK)
	}
}
func TestRunHeaderOnlyFileExitsZero(t *testing.T) {
	code, _, _ := runWith(t, "a,b\n")
	if code != exitOK {
		t.Fatalf("exit code = %d, want %d", code, exitOK)
	}
}
func TestRunRejectedInputExitsThreeWithEmptyStdout(t *testing.T) {
	cases := map[string]string{
		"empty file":        "",
		"blank lines only":  "\n\n\n",
		"empty header name": "id,,name\n1,x,y\n",
		"repeated header":   "id,name,id\n1,x,2\n",
		"ragged record":     "a,b\n1,2\n3,4,5\n6,7\n",
		"bare quote":        "a,b\n1\"x,2\n",
	}
	for name, content := range cases {
		t.Run(name, func(t *testing.T) {
			code, stdout, _ := runWith(t, content)
			if code != exitRejected {
				t.Fatalf("exit code = %d, want %d", code, exitRejected)
			}
			if stdout.Len() != 0 {
				t.Fatalf("stdout has %d bytes, want none", stdout.Len())
			}
		})
	}
}
func TestRunUsageErrorExitsTwoWithEmptyStdout(t *testing.T) {
	path := filepath.Join(t.TempDir(), "input.csv")
	if err := os.WriteFile(path, []byte("a,b\n1,2\n"), 0o600); err != nil {
		t.Fatalf("write input: %v", err)
	}
	cases := map[string][]string{
		"no arguments":      {},
		"option after file": {path, "--column", "a"},
		"unknown option":    {"--frobnicate", path},
	}
	for name, args := range cases {
		t.Run(name, func(t *testing.T) {
			code, stdout, _ := runArgs(t, args...)
			if code != exitUsage {
				t.Fatalf("exit code = %d, want %d", code, exitUsage)
			}
			if stdout.Len() != 0 {
				t.Fatalf("stdout has %d bytes, want none", stdout.Len())
			}
		})
	}
}
func TestRunMissingFileExitsOne(t *testing.T) {
	missing := filepath.Join(t.TempDir(), "absent.csv")
	code, stdout, _ := runArgs(t, missing)
	if code != exitOperational {
		t.Fatalf("exit code = %d, want %d", code, exitOperational)
	}
	if stdout.Len() != 0 {
		t.Fatalf("stdout has %d bytes, want none", stdout.Len())
	}
}
func TestRunValidFormsAreNotUsageErrors(t *testing.T) {
	path := filepath.Join(t.TempDir(), "input.csv")
	if err := os.WriteFile(path, []byte("a,b\n1,2\n"), 0o600); err != nil {
		t.Fatalf("write input: %v", err)
	}
	forms := [][]string{
		{path},
		{"--column", "a", path},
		{"--freq", "a", path},
		{"--freq", "a", "--top", "3", path},
	}
	for _, form := range forms {
		if code, _, _ := runArgs(t, form...); code == exitUsage {
			t.Errorf("Run(%q) exit code = %d, want non-usage", form, code)
		}
	}
}
// Package cli parses arguments, dispatches commands, maps failures to exit
// codes, and writes diagnostics to standard error.
package cli
package cli
import (
	"fmt"
	"strconv"
	"csvstat/internal/csvdata"
	"csvstat/internal/freq"
)
// defaultTop is the number of frequency rows listed when --top is not given.
const defaultTop = 5
// freqRows returns the header and the limited frequency listing of the --freq column.
func freqRows(t *csvdata.Table, opts Options) ([][]string, error) {
	c := columnIndex(t.Header, opts.Freq)
	if c < 0 {
		return nil, fmt.Errorf("no column named %q", opts.Freq)
	}
	limit := defaultTop
	if opts.TopSet {
		limit = opts.Top
	}
	entries := freq.Top(freq.Count(columnValues(t, c)), limit)
	rows := [][]string{{"value", "count"}}
	for _, entry := range entries {
		rows = append(rows, []string{entry.Value, strconv.Itoa(entry.Count)})
	}
	return rows, nil
}
// columnIndex returns the position of the header name, or -1 when no column has that name.
func columnIndex(header []string, name string) int {
	for i, column := range header {
		if column == name {
			return i
		}
	}
	return -1
}
package cli
import (
	"fmt"
	"os"
	"path/filepath"
	"reflect"
	"strings"
	"testing"
)
// freqRun runs --freq on the column of a file with content, followed by extra arguments.
func freqRun(t *testing.T, content, column string, extra ...string) (int, [][]string) {
	t.Helper()
	path := filepath.Join(t.TempDir(), "input.csv")
	if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
		t.Fatalf("write input: %v", err)
	}
	args := append([]string{"--freq", column}, extra...)
	args = append(args, path)
	code, stdout, _ := runArgs(t, args...)
	if code != exitOK {
		return code, nil
	}
	return code, parseOutput(t, stdout)
}
// sevenValues returns a column whose values v0..v6 occur 7, 6, ..., 1 times.
func sevenValues() string {
	var b strings.Builder
	b.WriteString("v\n")
	for i := 0; i < 7; i++ {
		for j := 0; j < 7-i; j++ {
			fmt.Fprintf(&b, "v%d\n", i)
		}
	}
	return b.String()
}
func TestFreqListsCountsInOrder(t *testing.T) {
	_, rows := freqRun(t, "v\nb\na\nb\nc\na\nb\n", "v")
	want := [][]string{{"value", "count"}, {"b", "3"}, {"a", "2"}, {"c", "1"}}
	if !reflect.DeepEqual(rows, want) {
		t.Fatalf("rows = %q, want %q", rows, want)
	}
}
func TestFreqDefaultTopIsFive(t *testing.T) {
	_, rows := freqRun(t, sevenValues(), "v")
	if len(rows) != 1+5 {
		t.Fatalf("got %d rows, want header plus 5", len(rows))
	}
	if want := []string{"v0", "7"}; !reflect.DeepEqual(rows[1], want) {
		t.Fatalf("first row = %q, want %q", rows[1], want)
	}
	if want := []string{"v4", "3"}; !reflect.DeepEqual(rows[5], want) {
		t.Fatalf("fifth row = %q, want %q", rows[5], want)
	}
}
func TestFreqExplicitTopLimitsAfterOrdering(t *testing.T) {
	_, rows := freqRun(t, sevenValues(), "v", "--top", "2")
	want := [][]string{{"value", "count"}, {"v0", "7"}, {"v1", "6"}}
	if !reflect.DeepEqual(rows, want) {
		t.Fatalf("rows = %q, want %q", rows, want)
	}
}
func TestFreqTopLargerThanDistinctListsAll(t *testing.T) {
	_, rows := freqRun(t, "v\na\nb\n", "v", "--top", "50")
	if len(rows) != 3 {
		t.Fatalf("got %d rows, want header plus 2", len(rows))
	}
}
func TestFreqHeaderOnlyListsHeaderOnly(t *testing.T) {
	_, rows := freqRun(t, "sku,price\n", "sku")
	if want := [][]string{{"value", "count"}}; !reflect.DeepEqual(rows, want) {
		t.Fatalf("rows = %q, want %q", rows, want)
	}
}
func TestFreqAllNullColumnListsHeaderOnly(t *testing.T) {
	_, rows := freqRun(t, "id,gap\n1,\n2,NA\n3, \n", "gap", "--top", "3")
	if want := [][]string{{"value", "count"}}; !reflect.DeepEqual(rows, want) {
		t.Fatalf("rows = %q, want %q", rows, want)
	}
}
func TestFreqQuotedValueRoundTrips(t *testing.T) {
	_, rows := freqRun(t, "notes\n\"relocating, TX\"\n\"relocating, TX\"\nother\n", "notes")
	if want := []string{"relocating, TX", "2"}; !reflect.DeepEqual(rows[1], want) {
		t.Fatalf("row 1 = %q, want %q", rows[1], want)
	}
	if want := []string{"other", "1"}; !reflect.DeepEqual(rows[2], want) {
		t.Fatalf("row 2 = %q, want %q", rows[2], want)
	}
}
func TestFreqUnknownColumnExitsTwoWithEmptyStdout(t *testing.T) {
	path := filepath.Join(t.TempDir(), "input.csv")
	if err := os.WriteFile(path, []byte("a,b\n1,2\n"), 0o600); err != nil {
		t.Fatalf("write input: %v", err)
	}
	code, stdout, _ := runArgs(t, "--freq", "missing", path)
	if code != exitUsage {
		t.Fatalf("exit code = %d, want %d", code, exitUsage)
	}
	if stdout.Len() != 0 {
		t.Fatalf("stdout has %d bytes, want none", stdout.Len())
	}
}
func TestFreqRaggedInputExitsThreeWithEmptyStdout(t *testing.T) {
	path := filepath.Join(t.TempDir(), "ragged.csv")
	if err := os.WriteFile(path, []byte("a,b\n1,2\n3\n"), 0o600); err != nil {
		t.Fatalf("write input: %v", err)
	}
	code, stdout, _ := runArgs(t, "--freq", "a", path)
	if code != exitRejected {
		t.Fatalf("exit code = %d, want %d", code, exitRejected)
	}
	if stdout.Len() != 0 {
		t.Fatalf("stdout has %d bytes, want none", stdout.Len())
	}
}
package cli
import (
	"math/big"
	"strconv"
	"csvstat/internal/csvdata"
	"csvstat/internal/profile"
)
// profileHeader is the first row of the default profile output.
var profileHeader = []string{"column", "type", "rows", "nulls", "distinct", "min", "max", "sum", "mean", "median"}
// profileRows returns the header and one row per column, in file order.
func profileRows(t *csvdata.Table) [][]string {
	rows := [][]string{profileHeader}
	for c, name := range t.Header {
		rows = append(rows, profileRow(name, columnValues(t, c)))
	}
	return rows
}
// profileRow computes one column's profile. Statistics that the column type does not carry are
// left blank.
func profileRow(name string, values []string) []string {
	typ := profile.InferType(values)
	counts := profile.Counts(values)
	extremes := profile.MinMax(typ, values)
	row := []string{
		name,
		typ,
		strconv.Itoa(counts.Rows),
		strconv.Itoa(counts.Nulls),
		strconv.Itoa(counts.Distinct),
		extremeText(typ, extremes.Min, extremes.MinRat),
		extremeText(typ, extremes.Max, extremes.MaxRat),
		"", "", "",
	}
	if sum, mean, ok := profile.SumMean(typ, values); ok {
		row[7] = sumText(typ, sum)
		row[8] = profile.FormatDecimal(mean)
	}
	if median, ok := profile.Median(typ, values); ok {
		row[9] = profile.FormatDecimal(median)
	}
	return row
}
// extremeText renders a minimum or maximum. Number extremes are written with two decimals;
// every other type is written as its text form.
func extremeText(typ string, text string, exact *big.Rat) string {
	if typ == profile.TypeNumber && exact != nil {
		return profile.FormatDecimal(exact)
	}
	return text
}
// sumText renders an exact sum: integer columns as plain integers, number columns with two decimals.
func sumText(typ string, sum *big.Rat) string {
	if typ == profile.TypeInteger {
		return profile.FormatInteger(sum)
	}
	return profile.FormatDecimal(sum)
}
// columnValues returns the trimmed value of column c for every data record, in file order.
func columnValues(t *csvdata.Table, c int) []string {
	values := make([]string, len(t.Records))
	for r, record := range t.Records {
		values[r] = record.Fields[c]
	}
	return values
}
package cli
import (
	"bytes"
	"encoding/csv"
	"reflect"
	"testing"
)
// parseOutput parses stdout as RFC 4180 CSV, failing the test if it is malformed.
func parseOutput(t *testing.T, stdout *bytes.Buffer) [][]string {
	t.Helper()
	rows, err := csv.NewReader(stdout).ReadAll()
	if err != nil {
		t.Fatalf("stdout is not CSV: %v\n%s", err, stdout.String())
	}
	return rows
}
// profileOf runs the default invocation on content and returns the parsed rows.
func profileOf(t *testing.T, content string) [][]string {
	t.Helper()
	code, stdout, _ := runWith(t, content)
	if code != exitOK {
		t.Fatalf("exit code = %d, want %d", code, exitOK)
	}
	return parseOutput(t, stdout)
}
func TestProfileHeaderAndColumnOrder(t *testing.T) {
	rows := profileOf(t, "id,label,price\n1,a,1.50\n2,b,2.25\n4,c,3.00\n")
	wantHeader := []string{"column", "type", "rows", "nulls", "distinct", "min", "max", "sum", "mean", "median"}
	if !reflect.DeepEqual(rows[0], wantHeader) {
		t.Fatalf("header = %q, want %q", rows[0], wantHeader)
	}
	var names, types []string
	for _, row := range rows[1:] {
		names = append(names, row[0])
		types = append(types, row[1])
	}
	if want := []string{"id", "label", "price"}; !reflect.DeepEqual(names, want) {
		t.Fatalf("columns = %q, want %q", names, want)
	}
	if want := []string{"integer", "text", "number"}; !reflect.DeepEqual(types, want) {
		t.Fatalf("types = %q, want %q", types, want)
	}
}
func TestProfileIntegerRow(t *testing.T) {
	rows := profileOf(t, "id,label,price\n1,a,1.50\n2,b,2.25\n4,c,3.00\n")
	want := []string{"id", "integer", "3", "0", "3", "1", "4", "7", "2.33", "2.00"}
	if !reflect.DeepEqual(rows[1], want) {
		t.Fatalf("integer row = %q, want %q", rows[1], want)
	}
}
func TestProfileNumberRow(t *testing.T) {
	rows := profileOf(t, "id,label,price\n1,a,1.50\n2,b,2.25\n4,c,3.00\n")
	want := []string{"price", "number", "3", "0", "3", "1.50", "3.00", "6.75", "2.25", "2.25"}
	if !reflect.DeepEqual(rows[3], want) {
		t.Fatalf("number row = %q, want %q", rows[3], want)
	}
}
func TestProfileTextRowHasBlankStatistics(t *testing.T) {
	rows := profileOf(t, "id,label,price\n1,a,1.50\n2,b,2.25\n4,c,3.00\n")
	want := []string{"label", "text", "3", "0", "3", "a", "c", "", "", ""}
