package csvdata

import (
	"encoding/csv"
	"fmt"
	"io"
)

// Record is one data record and the 1-based source line on which it starts.
type Record struct {
	Line   int
	Fields []string
}

// Table is a parsed CSV input: the header record and the data records after it.
type Table struct {
	Header  []string
	Records []Record
}

// Read parses r as RFC 4180 CSV. The first record is the header and every later
// record is a data record. Values are returned as parsed, untrimmed. Input with
// no record returns a nil Header and no error; Validate rejects it.
func Read(r io.Reader) (*Table, error) {
	cr := csv.NewReader(r)
	cr.FieldsPerRecord = -1
	cr.LazyQuotes = false

	var t Table
	header, err := cr.Read()
	if err == io.EOF {
		return &t, nil
	}
	if err != nil {
		return nil, fmt.Errorf("read csv: %w", err)
	}
	t.Header = header

	for {
		fields, err := cr.Read()
		if err == io.EOF {
			return &t, nil
		}
		if err != nil {
			return nil, fmt.Errorf("read csv: %w", err)
		}
		line, _ := cr.FieldPos(0)
		t.Records = append(t.Records, Record{Line: line, Fields: fields})
	}
}
package csvdata

import (
	"errors"
	"fmt"
)

// ErrRejected matches every input rejection with errors.Is.
var ErrRejected = errors.New("input rejected")

// RejectedError describes why an input was rejected. Line is the 1-based source
// line of the offending record, or 0 when the rejection concerns the header or
// the whole input.
type RejectedError struct {
	Line   int
	Reason string
}

func (e *RejectedError) Error() string {
	if e.Line == 0 {
		return e.Reason
	}
	return fmt.Sprintf("line %d: %s", e.Line, e.Reason)
}

// Unwrap makes errors.Is(err, ErrRejected) true for every RejectedError.
func (e *RejectedError) Unwrap() error {
	return ErrRejected
}

// Validate rejects input that must produce no output: no header record (empty
// or blank-only input), an empty or repeated header name, and any record whose
// field count differs from the header. Call it after Trim, so names compare as
// trimmed. A header-only table is valid.
func Validate(t *Table) error {
	if t.Header == nil {
		return &RejectedError{Reason: "no header record: input is empty or blank"}
	}

	seen := make(map[string]bool, len(t.Header))
	for i, name := range t.Header {
		if name == "" {
			return &RejectedError{Reason: fmt.Sprintf("header column %d is empty", i+1)}
		}
		if seen[name] {
			return &RejectedError{Reason: fmt.Sprintf("header name %q is repeated", name)}
		}
		seen[name] = true
	}

	for _, rec := range t.Records {
		if len(rec.Fields) != len(t.Header) {
			return &RejectedError{
				Line:   rec.Line,
				Reason: fmt.Sprintf("record has %d fields, header has %d", len(rec.Fields), len(t.Header)),
			}
		}
	}
	return nil
}
package csvdata

import "strings"

// Trim removes leading and trailing spaces (U+0020) from every header name and
// every record field, in place. Other whitespace and interior spaces are kept.
// Line numbers and field counts are unchanged.
func Trim(t *Table) {
	for i, name := range t.Header {
		t.Header[i] = strings.Trim(name, " ")
	}
	for r := range t.Records {
		fields := t.Records[r].Fields
		for i, value := range fields {
			fields[i] = strings.Trim(value, " ")
		}
	}
}
package csvdata

import "strings"

// IsNull reports whether value, already trimmed of leading and trailing spaces,
// is a null spelling: empty, or NA, N/A or NULL ignoring case. No other token
// is null.
func IsNull(value string) bool {
	return value == "" ||
		strings.EqualFold(value, "NA") ||
		strings.EqualFold(value, "N/A") ||
		strings.EqualFold(value, "NULL")
}

